-- Country dataset for te_countries: ISO 3166-1 alpha-2 + names/coords from world-countries 5.1.0;
-- populations are World Bank SP.POP.TOTL 2018 figures as published in country-json 2.3.0 (null where unavailable).
-- On conflict only names/coords refresh, so population edits made in the admin dashboard are kept.
on conflict (code) do update set name=excluded.name, region=excluded.region, lat=excluded.lat, lng=excluded.lng;
